-- koloni-286: Yönetici › Bilgi arşivi — konu klasörleri ve kayıtlar (yalnız yönetici; RLS sa_is_admin). Kullanıcı sayfalarında gösterilmez.
create table if not exists public.bilgi_klasorleri (id text primary key, ad text not null, aciklama text, sira int not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.bilgi_kayitlari (id text primary key, klasor_id text not null references public.bilgi_klasorleri(id) on delete cascade, baslik text not null, icerik text not null default '', durum text not null default 'uzman tahmini', kaynaklar jsonb not null default '[]'::jsonb, sira int not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
alter table public.bilgi_klasorleri enable row level security;
alter table public.bilgi_kayitlari enable row level security;
revoke all on public.bilgi_klasorleri, public.bilgi_kayitlari from anon;
grant select, insert, update, delete on public.bilgi_klasorleri, public.bilgi_kayitlari to authenticated;
drop policy if exists bilgi_klasorleri_admin on public.bilgi_klasorleri;
create policy bilgi_klasorleri_admin on public.bilgi_klasorleri for all to authenticated using (public.sa_is_admin()) with check (public.sa_is_admin());
drop policy if exists bilgi_kayitlari_admin on public.bilgi_kayitlari;
create policy bilgi_kayitlari_admin on public.bilgi_kayitlari for all to authenticated using (public.sa_is_admin()) with check (public.sa_is_admin());
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('irk','Arı ırkları ve bölge seçimi','Muğla, Antalya, Tekman/Erzurum ve üçü için tek ırk.',10) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-tekman','irk','Tekman (Erzurum): Erzurum yerel arısı','Öneri: Erzurum yerel ekotipi.
• Erzurum 1999: kışlama yaşama gücü Erzurum %100, Orta Anadolu %90, Kafkas %81,8; kışta nüfus kaybı Erzurum %32, Kafkas %47.
• Bal: Erzurum 35,4 · Orta Anadolu 32,6 · Kafkas 30,6 kg/koloni. En sakin Kafkas, en yağmacı Orta Anadolu; oğul eğilimi benzer.
• Doğu Anadolu 2017: Karniyol 29,9 · Buckfast 28,1 · Erzurum 23,4 · Kafkas 19,3 kg; Kafkas kışta en çok nüfus kaybetti.
Yedek: Karniyol veya Kafkas × Karniyol (Palandöken) — melezin kendisi ölçülmedi: uzman tahmini.
Kafkas × Karadeniz (Tortum): Erzurum çalışması yok — Veri yok.
Hastalık direnci: Veri yok. Zayıflık: grup başı 10–12 koloni, 1–2 yıl.','karışık','[{"ad":"Kafkas, Orta Anadolu ve Erzurum Balarısı Genotiplerinin Erzurum Koşullarındaki Bazı Fizyolojik Özelliklerinin Karşılaştırılması (Turk J Vet Anim Sci 23, 1999)","url":"https://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek4/vet-23-ek4-1-97040.pdf"},{"ad":"Kafkas, Anadolu ve Erzurum balarısı genotiplerinin Erzurum koşullarındaki performansları (tez özeti)","url":"https://tezara.org/theses/58504"},{"ad":"Doğu Anadolu Koşullarında Farklı Bal Arısı Genotiplerinin Kışlama Yeteneği ve Koloni Performanslarının Karşılaştırılması (Kafkas Üniv Vet Fak Derg, 2017)","url":"https://doi.org/10.9775/kvfd.2017.17667"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-mugla','irk','Muğla (Kayaköy, çam balı): Muğla arısı','Öneri: Muğla arısı (A. m. anatoliaca, Ege ekotipi).
• Gezginci 6 genotip, 2 yıl: yıllık bal Muğla 50,2 · Alata 43,5 · Gökçeada 41,2 · Kafkas 26,6 · Orta Anadolu 20,6 · Trakya 15,9 kg.
• Akyol: 2. yıl Muğla ana × Kafkas baba 65,0 · Muğla 53,9 · Kafkas 33,0 kg; en hırçın Muğla × Kafkas.
• Ege''de Kafkas küçük koloni, az bal.
• Çam balında İtalyan melezi 37,1 kg, Muğla 21,3 kg; Muğla çevreye daha uyumlu.
Yedek: Muğla × Kafkas melezi (daha hırçın), İtalyan melezi (uyumu düşük). Saf Kafkas önerilmez.','kaynaklı','[{"ad":"Güler & Kaftanoğlu (1999), Türkiye''deki Önemli Balarısı Irk ve Ekotiplerinin Göçer Arıcılık Koşullarında Performanslarının Karşılaştırılması (Turk J Vet Anim Sci 23)","url":"http://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek3/vet-23-ek3-22-98022.pdf"},{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"},{"ad":"Kafkas, İtalyan Irkları ve Anadolu Arısı Ege Ekotipi ile Bazı Melezlerinin Ege Bölgesi Koşullarında Koloni Gelişimleri (ADÜ Tralleis)","url":"http://dergi.adu.edu.tr/tralleis/index.php/tralleis/article/view/7"},{"ad":"Yücel & Kösoğlu (2011), Ege Bölgesi''nde Muğla Ekotipi ve İtalyan Melezi Bal Arılarının Kimi Performans Özellikleri (Kafkas Üniv Vet Fak Derg 17(6))","url":"https://vetdergikafkas.org/pdf.php?id=1037"}]'::jsonb,20) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-antalya','irk','Antalya (sahil + Toros yaylası): yerel Akdeniz/Toros arısı','Öneri: yerel Akdeniz/Toros arısı — uzman tahmini.
• Antalya arısı morfolojik olarak ayrı grup; performans ölçümü: Veri yok.
• Gezginci denemede Muğla 50,2 kg, Akdeniz/Alata (Mersin) 43,5 kg, Kafkas 26,6 kg.
Sahil ve yayla ayrı karşılaştırma: Veri yok.
Yedek: Muğla arısı (Antalya''da denenmedi: uzman tahmini).','uzman tahmini','[{"ad":"Türkiye''nin Akdeniz Bölgesine Özgü Bal Arısı Populasyonlarında Morfolojik Çeşitliliğinin Araştırılması","url":"https://doi.org/10.59287/tosbgy.979"},{"ad":"Güler & Kaftanoğlu (1999), Türkiye''deki Önemli Balarısı Irk ve Ekotiplerinin Göçer Arıcılık Koşullarında Performanslarının Karşılaştırılması (Turk J Vet Anim Sci 23)","url":"http://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek3/vet-23-ek3-22-98022.pdf"}]'::jsonb,30) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-tek','irk','Üç yer için tek ırk: Muğla arısı','Öneri: Muğla arısı — uzman tahmini (üç bölgeyi birlikte deneyen çalışma yok).
Sıcak (Ege/Akdeniz gezginci): Muğla 1. (50,2 kg) · Karniyol Veri yok · Kafkas zayıf (26,6).
Ilıman (Orta Anadolu 2014): Karniyol 31,6 · Muğla 28,6 · Kafkas 23,4 · Niğde 15,4 kg.
Soğuk (Erzurum): Muğla Veri yok · Karniyol 1. (29,9) · Kafkas en zayıf (19,3) · Erzurum yerel kışlama %100.
Ödünleşim: Muğla arısının Erzurum kışlaması bilinmiyor → Tekman''da güçlü kışlatma ve bol stok (uzman tahmini). Yedek: Karniyol (Akdeniz/çam balı Veri yok). Kafkas üç bölgede de zayıf.','uzman tahmini','[{"ad":"Güler & Kaftanoğlu (1999), Türkiye''deki Önemli Balarısı Irk ve Ekotiplerinin Göçer Arıcılık Koşullarında Performanslarının Karşılaştırılması (Turk J Vet Anim Sci 23)","url":"http://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek3/vet-23-ek3-22-98022.pdf"},{"ad":"Comparison of Colony Performances of Anatolian, Caucasian and Carniolan Honeybee Genotypes in Temperate Climate Conditions (Ital J Anim Sci, 2014)","url":"https://www.tandfonline.com/doi/full/10.4081/ijas.2014.3409"},{"ad":"Doğu Anadolu Koşullarında Farklı Bal Arısı Genotiplerinin Kışlama Yeteneği ve Koloni Performanslarının Karşılaştırılması (Kafkas Üniv Vet Fak Derg, 2017)","url":"https://doi.org/10.9775/kvfd.2017.17667"},{"ad":"Kafkas, Orta Anadolu ve Erzurum Balarısı Genotiplerinin Erzurum Koşullarındaki Bazı Fizyolojik Özelliklerinin Karşılaştırılması (Turk J Vet Anim Sci 23, 1999)","url":"https://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek4/vet-23-ek4-1-97040.pdf"},{"ad":"Kafkas, İtalyan Irkları ve Anadolu Arısı Ege Ekotipi ile Bazı Melezlerinin Ege Bölgesi Koşullarında Koloni Gelişimleri (ADÜ Tralleis)","url":"http://dergi.adu.edu.tr/tralleis/index.php/tralleis/article/view/7"},{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"}]'::jsonb,40) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('goc','Gezginci göç ve verim tahmini','Antalya → Tekman → Muğla güzergâhı.',20) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('goc-tahmin','goc','Antalya → Tekman → Muğla verim tahmini','Tamamı uzman tahmini; bu güzergâh ve melez birlikte denenmedi.
• Antalya ilkbahar (narenciye, kekik): 5–15 kg (koloni büyür, tüketir).
• Tekman yayla Haziran–Ağustos: 10–25 kg.
• Muğla Kayaköy çam balı Ağustos–Kasım: 10–25 kg (kış stoğu bırakıldıktan sonra).
• Toplam: 25–65 kg/koloni; beklenen ≈35–50 kg.
Dayanaklar: Akyol melez gezginci yıl 16–65 kg; Güler & Kaftanoğlu Muğla 50,2 kg; TÜİK 2023 il ortalaması Muğla 9,9 · Antalya 8,9 · Erzurum 8,8 kg (Türkiye 12,45) — taban.
Narenciye, kekik, Tekman yayla ve Kayaköy çam balı için koloni başı ölçülmüş verim: Veri yok.','uzman tahmini','[{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"},{"ad":"Güler & Kaftanoğlu (1999), Türkiye''deki Önemli Balarısı Irk ve Ekotiplerinin Göçer Arıcılık Koşullarında Performanslarının Karşılaştırılması (Turk J Vet Anim Sci 23)","url":"http://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek3/vet-23-ek3-22-98022.pdf"},{"ad":"TEPGE / STB Arıcılık Ürün Raporu 2024 (TÜİK 2023 il verileri)","url":"https://stb.org.tr/uploads/arastirmalar/dokuman/arastirmalar/aricilik-urun-raporu-2024-1721631134-8.pdf"},{"ad":"Arıcılık Araştırma Enstitüsü — Türkiye Arıcılık İstatistikleri","url":"https://arastirma.tarimorman.gov.tr/aricilik/"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('melez','Muğla ana × Kafkas baba melezi','Akyol (1998) verisi, 65 kg için yapılacaklar, riskler.',30) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('melez-veri','melez','Akyol (1998) / Akyol & Kaftanoğlu (2001) verisi','Gezginci arıcılık, 1996–1997. Ana arılar yapay tohumlandı, 1996 ilkbaharında 5 çerçeveli kolonilere verildi. Güzergâh ve arılık yeri: Veri yok (tam metin yok; çalışma Çukurova Üniv.). Grup başı ≈11 koloni (yaşama oranlarından çıkarım).
Bal (kg/koloni) 1996 → 1997:
• Muğla × Kafkas: 16,15 → 65,00
• Muğla × Muğla: 15,05 → 53,90
• Kafkas × Kafkas: 11,40 → 33,00
• Kafkas × Muğla: 9,55 → 32,25
Kışlama: M×K %91,7 (fark anlamlı değil). Arılı çerçeve M×K 11,56, yavru ≈2.814 cm², koloni ağırlığı 43,2 kg. Korelasyon bal–arılı çerçeve r=0,85, yavru r=0,82, ağırlık r=0,95. En hırçın M×K, en sakin saf Kafkas.
Kat / ballık sayısı: Veri yok.','kaynaklı','[{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"},{"ad":"Akyol & Kaftanoğlu (2001), Colony characteristics and the performance of Caucasian and Mugla bees and their reciprocal crosses (özet)","url":"https://hdl.handle.net/11480/5761"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('melez-65','melez','65 kg için yapılacaklar','Kaynaklı:
• Her yıl genç ana arı (göçerde yıllık değişim; ≈%30 verim artışı). 0–1 yaş 31–42 kg, 2–3 yaş 12–20 kg.
• Melez yapay tohumlama ile; F1 kızları aynı melez olmaz → her yıl tohumlanmış ana alın veya kontrollü çiftleştirin (uzman tahmini).
• Güçlü koloni: verim arılı çerçeveyle r=0,85.
• Bal akımında ilaç yok; laktik asit akımdan en geç 4 hafta önce; sonbahar mücadelesi son hasattan sonra.
• Taşıma gece.
• İlk yıl 16 kg: 5 çerçeveli kuruluş yılı → koloniyi bir yıl önce kurun.
Durak durak (uzman tahmini kısımlar): Antalya — varroa, uyarıcı besleme, erken yer, oğul kontrolü; Tekman''a ≥10 arılı çerçeveyle gece taşıma; Tekman — erken ballık, Ağustos hasat, akım arası varroa; Muğla — çam balında ilaç yok, sonra sonbahar mücadelesi, kış stoğu (miktar uzman tahmini), ana arı yenileme.
Riskler: en hırçın genotip; verim yıldan yıla 16–65 kg; Erzurum soğuğunda denenmedi.','karışık','[{"ad":"Şerefoğlu & Canverdi, Ana Arı Yetiştiriciliğinin Önemi ve Ana Arının Kalitesine Etki Eden Faktörler (Arıcılık Araştırma Dergisi, Ordu)","url":"https://www.beestudies.org/pdf.php?id=125"},{"ad":"An observation study on the effects of queen age on some characteristics of honey bee colonies (Ital J Anim Sci, 2008)","url":"https://doi.org/10.4081/ijas.2008.19"},{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"},{"ad":"Arıcılık Araştırma Enstitüsü, Arı Hastalıkları kitapçığı (2022)","url":"https://arastirma.tarimorman.gov.tr/aricilik/Belgeler/kitapc%C4%B1klar/kitapc%C4%B1k%202022%20yeni/ar%C4%B1%20hastal%C4%B1klar%C4%B12022-2.pdf"},{"ad":"KOP, Üretici Rehberi – Arıcılık","url":"https://kop.gov.tr/storage/documents/218.pdf"}]'::jsonb,20) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('ballik','Ballık / kat kapasitesi','Langstroth kat ve çerçeve bal kapasitesi.',40) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('ballik-kap','ballik','65 kg kaç ballık eder','Akyol''da kat sayısı: Veri yok. 11,6 arılı çerçeve ≈ dip + 1 ballık doluluğu (uzman tahmini).
• Langstroth tam boy dolu çerçeve ≈3–4,5 kg (çerçeve+petek dahil); dolu 10 çerçeveli kat ≈36–40 kg; süzülebilir net ≈25–30 kg (süzme %80–90 varsayımı).
• Yarım kat (17 cm): çerçeve ≈2,3–2,7 kg, kat ≈20–25 kg.
• 65 kg: sezonda toplam 2–3 tam boy veya ≈3 yarım kat.
• Güzergâhta bal üç durakta alınacağı için her durakta dip + 1–2 ballık yeterli (uzman tahmini).
Türk kaynaklı ölçülmüş çerçeve kapasitesi: Veri yok.','karışık','[{"ad":"Langstroth Hive Dimensions Chart (HiveStart)","url":"https://hivestart.net/guides/langstroth-hive-dimensions/"},{"ad":"How Much Honey Per Frame? (Utah State Univ. Extension atıflı)","url":"https://beekeepertips.com/how-much-honey-per-frame/"},{"ad":"Oh Honey, Honey: Considerations for New Beekeepers","url":"https://nodglobal.com/oh-honey-honey-considerations-for-new-beekeepers/"},{"ad":"Yarım kat ballık (arıcı blogu, akademik değil)","url":"http://muratakin26.blogspot.com/search/label/yar%C4%B1m%20kat%20ball%C4%B1k"},{"ad":"Akyol (1998), Kafkas ve Muğla Arılarının Saf ve Karşılıklı Melezlerinin Morfolojik, Fizyolojik ve Davranışsal Özelliklerinin Belirlenmesi (doktora tezi özeti; tam metin yok)","url":"https://tezara.org/theses/77039"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('konum','Arılık konumu – Tekman foraj seçimi','Tekman Arılığı iğnesi (koloni-285).',50) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('konum-tekman','konum','Tekman: 39.675, 41.404 (~2155 m, Düzyurt doğusu)','İlçe merkezi (39.645, 41.5083) yerine ilçe sınırı içinde ≈400 m ızgara tarandı. Nokta CORINE 321 doğal çayır içinde; 2,5 km yarıçapta %82 doğal çayır + %5 mera + %5 karışık tarım-doğal, %0 ekili tarla, %7 seyrek bitki, %1 yerleşim. WorldCover 2 km: %97 çayır. Eğim ≈1°, dere ≈430 m, tali yol ≈540 m, Düzyurt ≈2,2 km, Geçit (≈1000 kovanlı yerel arıcı) ≈6 km kuzeyde.
Flora ve dönem (TAGEM): Haziran–Ağustos; yonca, kekik, civan perçemi, adaçayı, korunga, üçgül, taş yoncası, geven.
Ağırlıklar ve eşikler (köy ≥1,5 km, su ≤0,5 km, yol ≤1 km, 1950–2300 m): uzman tahmini. Yerinde flora sayımı: Veri yok — Yapılacaklar''da.','karışık','[{"ad":"CORINE Land Cover 2018 (EEA, Copernicus)","url":"https://land.copernicus.eu/en/products/corine-land-cover"},{"ad":"ESA WorldCover 10 m 2021 v200","url":"https://esa-worldcover.org/"},{"ad":"Copernicus DEM GLO-30","url":"https://spacedata.copernicus.eu/collections/copernicus-digital-elevation-model"},{"ad":"OpenStreetMap (Overpass, 18.10.2026)","url":"https://www.openstreetmap.org/"},{"ad":"Cınbırtoğlu (haz.), İl ve İlçelere Göre Çiçeklenme Dönemi, TAGEM Ordu Arıcılık Araştırma Enstitüsü 2022","url":"https://arastirma.tarimorman.gov.tr/aricilik/"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('ogul','Oğul dönemi','Oğul mevsimi pencereleri ve çam balı.',60) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('ogul-mugla','ogul','Muğla: oğul yalnız ilkbaharda; çam balı bal akımıdır','Oğul ekranında bal mevsimine değil oğul dönemine bakılır. Muğla (sıcak bölge) oğul penceresi 15 Mart–10 Mayıs. Çam balı dönemi (15 Ağu–30 Kas) bal akımıdır, oğul mevsimi değil; Akdeniz arısında oğul ilkbaharda. Sonbahar doğal oğul penceresi için doğrulanmış veri: Veri yok. Ekran etiketi «Oğul dönemi değil» (koloni-284).
Bölge pencereleri (Sıcak 15 Mar–10 May · Ilıman 20 Nis–31 May · Yayla 25 May–30 Haz · Yüksek yayla 5 Haz–5 Tem): kaynaksız, uzman tahmini (Yapılacaklar).','karışık','[{"ad":"TÜRKPATENT coğrafi işaret «Muğla Çam Balı»","url":"https://ci.turkpatent.gov.tr/"},{"ad":"Tiemann & Brückner 1993, Apidologie 24(4) (Sicilya, oğul ilkbaharda)","url":"https://www.apidologie.org/"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_klasorleri (id,ad,aciklama,sira) values ('donanim','Donanım','Parçalar, dış ortam/nem, pil sıcaklığı, kaplama. Ayrıntı: Yönetici › Donanım.',70) on conflict (id) do update set ad=excluded.ad, aciklama=excluded.aciklama, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('don-parca','donanim','Parçalar ve alternatifler','Düğüm: LilyGO T-Weigh (ESP32-S3 + HX711). Gateway: LilyGO T-Beam V1.2 + SIMCom A7670E.
Alternatifler (aynı yazılım, aynı iş): SHT45/43/40-AD1B/40-AD1F; MAX31820 ve DS18S20 (DS18B20 yerine); INMP441 (uzman tahmini, NRND).
Yedek düzen: T-Weigh, SHT41, DS18B20, INMP441, ADXL345.
Maliyet: 1 kovan 2.517,61 TL, 1 gateway 8.724,26 TL, soğuk bölge eki 11,26 TL/gateway (TCMB 1 USD = 49,4463 TL, 16.10.2026).','kaynaklı','[{"ad":"Sensirion SHT4x datasheet V7.3","url":"https://sensirion.com/media/documents/33FD6951/6A7C10A0/HT_DS_Datasheet_SHT4x_V7.3.pdf"},{"ad":"Analog MAX31820","url":"https://www.analog.com/en/products/max31820.html"},{"ad":"Analog DS18S20","url":"https://www.analog.com/en/products/ds18s20.html"},{"ad":"TDK InvenSense INMP441","url":"https://product.tdk.com/en/search/sw_piezo/mic/mems-mic/info?part_no=INMP441"},{"ad":"LilyGO T-Beam ürün sayfası","url":"https://lilygo.cc/products/t-beam"},{"ad":"SIMCom A7670 Series Hardware Design","url":"https://nostris.ee/pdf/A7670%20Series%20Hardware%20Design_V1.00.pdf"}]'::jsonb,10) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('don-ortam','donanim','Dış ortam ve nem','• SHT41: −40…125 °C, 0–100 %RH; >80 %RH uzun süre geçici kayma; ısıtıcı görev oranı ≤%10.
• SHT40-AD1F: polyimid membran, IP68. SF2 filtre kapağı: PTFE, IP67.
• IP67 = toz geçirmez + 1 m 30 dk; kutuya PTFE nefes tapası + IP68 rakor.
• T-Beam: 868 MHz için üretici SX1276 yazıyor, yapılandırmamız SX1262 → satıcıya sorulmalı. Kartın sıcaklık/nem/IP değeri: Veri yok.
• A7670E: −30…80 °C normal, −40…85 °C genişletilmiş.
• Tuzlu hava (Fethiye) kaplama zorunlu: uzman tahmini.','karışık','[{"ad":"Sensirion SHT4x datasheet V7.3","url":"https://sensirion.com/media/documents/33FD6951/6A7C10A0/HT_DS_Datasheet_SHT4x_V7.3.pdf"},{"ad":"Sensirion SF2 Filter Cap datasheet","url":"https://sensirion.com/media/documents/356EC75F/61642475/Sensirion_Humidity_Sensors_SF2_Filter_Cap_Datasheet.pdf"},{"ad":"IEC 60529 IP testleri (CSA Group)","url":"https://www.csagroup.org/en-gb/services/lab-testing-calibration/ingress-protection-ip-testing/"},{"ad":"LilyGO T-Beam ürün sayfası","url":"https://lilygo.cc/products/t-beam"},{"ad":"SIMCom A7670 Series Hardware Design","url":"https://nostris.ee/pdf/A7670%20Series%20Hardware%20Design_V1.00.pdf"}]'::jsonb,20) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('don-pil','donanim','Pil sıcaklık sınırları','• Samsung 35E (18650): şarj 0…45 °C, deşarj −10…60 °C → Erzurum (−30 °C) için «Uygun değil» (korumasız).
• LiFePO4 de 0 °C altında şarj edilmez (deşarj −20…60 °C).
• T-Beam V1.2''de pil NTC''si yok: AXP2101 TS ucu 100 Ω ile toprağa bağlı → 0 °C altında şarjı donanım kesmez.
• Çözüm: 10K NTC ile pil sıcaklığı ölçülüp şarj yazılımla kesilir; yalıtımlı/ısıtmalı paket (soğuk bölge eki). Güneşte 45 °C üstü: gölge (uzman tahmini).','karışık','[{"ad":"Samsung INR18650-35E datasheet","url":"https://www.orbtronic.com/content/samsung-35e-datasheet-inr18650-35e.pdf"},{"ad":"LiFePO4 18650 datasheet","url":"https://www.antbatt.com/wp-content/uploads/2019/09/18650-3.2V-1800mAh-datasheet.pdf"},{"ad":"LilyGO T-Beam V1.2 şeması","url":"https://github.com/Xinyuan-LilyGO/LilyGo-LoRa-Series/blob/master/schematic/LilyGo_TBeam_V1.2-lastest.pdf"},{"ad":"X-Powers AXP2101 datasheet","url":"https://files.waveshare.com/wiki/common/X-power-AXP2101_SWcharge_V1.0.pdf"}]'::jsonb,30) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('don-kaplama','donanim','Epoksi mi, kaplama verniği mi','Kartın tamamını epoksiye gömmeyin; kaplama verniği (conformal coating) + IP67 kutu + silika jel + nefes tapası kullanın. Gerekçe (ısı dağılımı, onarım, anten/sensör erişimi): uzman tahmini — doğrudan kaynak: Veri yok.','uzman tahmini','[{"ad":"IEC 60529 IP testleri (CSA Group)","url":"https://www.csagroup.org/en-gb/services/lab-testing-calibration/ingress-protection-ip-testing/"}]'::jsonb,40) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
